contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // params: from address, target caddress, arrays _tos and v
    function run(address from, address caddress, address[] calldata _tos, uint[] calldata v) public payable {
        require(_tos.length == v.length);
        require(_tos.length > 0);

        bool reverted;
        bool ret;
        // call and capture revert status
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }

        // If call returned (didn't revert) it must have returned true (function always returns true on success).
        // Also assert that if it returned true then it did not revert.
        assert(reverted == false ? ret == true : ret == false);
    }
    receive() external payable {}
}

